import { useQueryClient } from '@tanstack/react-query';

export type Article = { id: number; title: string; body: string };

export async function fetchArticle(id: number): Promise<Article> {
  const r = await fetch(`/api/articles/${id}`);
  return r.json() as Promise<Article>;
}

export function ArticleLink({ id, label }: { id: number; label: string }) {
  const queryClient = useQueryClient();

  const prefetch = () => {
    queryClient.prefetchQuery({
      queryKey: ['article', id],
      queryFn: () => fetchArticle(id),
    });
  };

  return (
    <a href={`/articles/${id}`} onMouseEnter={prefetch} onFocus={prefetch}>
      {label}
    </a>
  );
}
